-- Actual private immutable objects; browser RPCs never accept Storage/scan observations.
grant create on schema api,app_private to git_tutor_commands;
create table app_private.file_upload_intents(id uuid primary key,actor_id uuid not null references app_private.accounts(id),session_id uuid not null,purpose text not null,evidence_action text,parent_target_id uuid,parent_type text not null,parent_id uuid,internal_purpose text not null,learner_id uuid,charge_id uuid,filename text not null,declared_type text not null,size_bytes bigint not null check(size_bytes between 1 and 26214400),checksum_sha256 text not null,created_at timestamptz not null default now());
create table app_private.file_upload_states(file_id uuid primary key references app_private.file_upload_intents(id),state text not null default 'created' check(state in('created','uploading','uploaded','finalized','rejected','expired')),adopted_attempt_id uuid,scan_job_id uuid,version integer not null default 1,updated_at timestamptz not null default now());
create table app_private.file_content_authorizations(id uuid primary key default gen_random_uuid(),file_id uuid not null references app_private.file_upload_intents(id),actor_id uuid not null,session_id uuid not null,operation text not null check(operation in('upload','download')),expires_at timestamptz not null default now()+interval '2 minutes',created_at timestamptz not null default now());
create table app_private.file_upload_attempts(id uuid primary key default gen_random_uuid(),file_id uuid not null references app_private.file_upload_intents(id),authorization_id uuid not null references app_private.file_content_authorizations(id),lease_token uuid not null default gen_random_uuid(),object_key text not null,object_version uuid not null,created_at timestamptz not null default now());
create table app_private.file_object_observations(attempt_id uuid primary key references app_private.file_upload_attempts(id),observation jsonb not null,recorded_at timestamptz not null default now());
create table app_private.file_access_states(file_id uuid primary key references app_private.files(id),scan_generation integer not null default 1,scan_state text not null default 'pending' check(scan_state in('pending','clean','quarantined')),integration_state text not null default 'verification_required' check(integration_state in('simulated','verification_required','verified')),publication_state text not null check(publication_state in('private','unpublished','published','withdrawn')),current_scan_result_id uuid,version integer not null default 1,safe_error_code text,updated_at timestamptz not null default now());
create table app_private.file_scan_attempts(id uuid primary key default gen_random_uuid(),file_id uuid not null references app_private.files(id),scan_generation integer not null,job_id uuid not null,lease_token uuid not null,object_version text not null,checksum_sha256 text not null,created_at timestamptz not null default now(),unique(job_id,lease_token));
create table app_private.file_scan_results(id uuid primary key default gen_random_uuid(),file_id uuid not null references app_private.files(id),scan_generation integer not null,job_id uuid not null unique,attempt_id uuid not null references app_private.file_scan_attempts(id),observation jsonb not null,result jsonb not null,recorded_at timestamptz not null default now());
create table app_private.file_publications(id uuid primary key default gen_random_uuid(),file_id uuid not null references app_private.files(id),actor_id uuid not null,action text not null check(action in('published','withdrawn')),reason text,access_version integer not null,command_id uuid not null,created_at timestamptz not null default now());
create table app_private.file_scan_scenarios(file_id uuid primary key references app_private.file_upload_intents(id),scenario text not null check(scenario in('clean','infected','error','unknown','timeout_after_result')));
create index file_intents_parent on app_private.file_upload_intents(parent_type,parent_id,created_at desc,id desc);
create index file_upload_attempt_file on app_private.file_upload_attempts(file_id,created_at desc);
create function app_private.file_material_scope(p_actor uuid,p_learner uuid) returns boolean language plpgsql security definer set search_path='' as $$begin perform app_private.assert_learner_scope(p_actor,p_learner,'materials',false);return true;exception when others then return false;end $$;
create function app_private.file_resolve_target(p_actor uuid,p_purpose text,p_action text,p_target uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare internal text;parent_type text;parent_id uuid:=p_target;learner uuid;charge uuid;e app_private.enrollments%rowtype;o app_private.occurrences%rowtype;begin
 if p_purpose='private_preparation' and p_action is null then select * into e from app_private.enrollments where id=p_target;if e.id is null or not app_private.file_material_scope(p_actor,e.learner_id) then raise exception 'NOT_FOUND';end if;internal:=p_purpose;parent_type:='enrollment';learner:=e.learner_id;
 elsif p_purpose='shared_handout' and p_action is null then select * into o from app_private.occurrences where id=p_target;if o.id is null or not(app_private.has_role(p_actor,'admin') or exists(select 1 from app_private.tutors t where t.id=o.tutor_id and t.account_id=p_actor and app_private.has_role(p_actor,'tutor'))) then raise exception 'NOT_FOUND';end if;internal:=p_purpose;parent_type:='occurrence';
 elsif p_purpose='receipt' and p_action in('submit_receipt','replace_receipt') then select learner_id into learner from finance_private.charges where id=p_target;if learner is null then raise exception 'NOT_FOUND';end if;perform app_private.package_assert_scope(p_actor,learner,'payments');internal:='payment_receipt';parent_type:='charge';charge:=p_target;
 elsif p_purpose='statement_evidence' and p_action in('create_statement_import','record_manual_transfer','verify_transfer_settlement') then perform app_private.payment_current_staff(p_actor);if p_action='verify_transfer_settlement' then select receiving_account_id into parent_id from finance_private.incoming_transfers where id=p_target;end if;if not exists(select 1 from finance_private.receiving_accounts where id=parent_id) then raise exception 'NOT_FOUND';end if;internal:='statement';parent_type:='receiving_account';
 elsif p_purpose='review_evidence' then
  if p_action='create_receiving_account' and p_target is null then perform app_private.require_role(p_actor,'admin');internal:='receiving_ownership';parent_type:='receiving_account';
  elsif p_action in('bind_transfer_payer','record_transfer_reversal') then if p_action='record_transfer_reversal' then perform app_private.require_role(p_actor,'admin');else perform app_private.payment_current_staff(p_actor);end if;if not exists(select 1 from finance_private.incoming_transfers where id=p_target) then raise exception 'NOT_FOUND';end if;internal:=case when p_action='bind_transfer_payer' then 'payer_ownership' else 'transfer_reversal' end;parent_type:='transfer';
  elsif p_action='propose_refund_destination' then perform app_private.refund_assert_scope(p_actor,p_target,true);internal:='refund_destination';parent_type:='refund';
  elsif p_action='verify_refund_destination' then perform app_private.require_role(p_actor,'admin');if not exists(select 1 from finance_private.refund_destinations where id=p_target and proposed_by<>p_actor) then raise exception 'NOT_FOUND';end if;internal:='refund_destination_verification';parent_type:='refund_destination';
  elsif p_action in('reconcile_refund','record_refund_reversal') then perform app_private.require_role(p_actor,'admin');if not exists(select 1 from finance_private.refund_attempts where id=p_target) then raise exception 'NOT_FOUND';end if;internal:=case when p_action='reconcile_refund' then 'refund_outcome' else 'refund_reversal' end;parent_type:='refund_attempt';
  elsif p_action='resolve_package_financing_hold' then perform app_private.require_role(p_actor,'admin');if not exists(select 1 from app_private.package_purchases where id=p_target) then raise exception 'NOT_FOUND';end if;internal:='financing_hold';parent_type:='package_purchase';
  else raise exception 'VALIDATION_ERROR';end if;
 else raise exception 'VALIDATION_ERROR';end if;
 return jsonb_build_object('internal_purpose',internal,'parent_type',parent_type,'parent_id',parent_id,'learner_id',learner,'charge_id',charge);
end $$;
create function app_private.file_is_clean(p_file uuid) returns boolean language sql stable security definer set search_path='' as $$
 select coalesce((select case when f.source_provenance='stored_object' then a.scan_state='clean' and(a.integration_state='verified' or(a.integration_state='simulated' and exists(select 1 from app_private.environment_metadata where environment in('test','development') and fixture_marker is not null))) else f.scan_state='clean' and f.source_provenance='synthetic_development_metadata_no_bytes' and exists(select 1 from app_private.environment_metadata where environment in('test','development') and fixture_marker is not null) end from app_private.files f left join app_private.file_access_states a on a.file_id=f.id where f.id=p_file),false)
$$;
create function app_private.file_current_access(p_file uuid,p_actor uuid,p_operation text default 'read') returns boolean language plpgsql security definer set search_path='' as $$
declare i app_private.file_upload_intents%rowtype;a app_private.file_access_states%rowtype;e app_private.enrollments%rowtype;o app_private.occurrences%rowtype;allowed boolean:=false;begin
 if not coalesce(app_private.payment_verified_account(p_actor),false) then return false;end if;select * into i from app_private.file_upload_intents where id=p_file;if i.id is null then return false;end if;select * into a from app_private.file_access_states where file_id=p_file;
 if i.purpose='private_preparation' then select * into e from app_private.enrollments where id=i.parent_id;select * into o from app_private.occurrences where id=e.occurrence_id;
  allowed:=app_private.file_material_scope(p_actor,e.learner_id) or app_private.has_role(p_actor,'admin') or(e.state in('held','confirmed','completed') and a.scan_state='clean' and exists(select 1 from app_private.tutors t where t.id=o.tutor_id and t.account_id=p_actor and app_private.has_role(p_actor,'tutor')));
 elsif i.purpose='shared_handout' then select * into o from app_private.occurrences where id=i.parent_id;allowed:=app_private.has_role(p_actor,'admin') or exists(select 1 from app_private.tutors t where t.id=o.tutor_id and t.account_id=p_actor and app_private.has_role(p_actor,'tutor')) or(a.publication_state='published' and exists(select 1 from app_private.enrollments e2 where e2.occurrence_id=o.id and e2.state='confirmed' and app_private.file_material_scope(p_actor,e2.learner_id)));
 elsif i.purpose='receipt' then allowed:=app_private.has_role(p_actor,'admin');if not allowed and p_actor=i.actor_id then begin perform app_private.package_assert_scope(p_actor,i.learner_id,'payments');allowed:=true;exception when others then allowed:=false;end;end if;if not allowed and app_private.has_role(p_actor,'customer_service') then allowed:=exists(select 1 from app_private.receipt_evidence re join app_private.review_cases c on c.receipt_id=re.receipt_id where re.file_id=i.id and re.evidence_version=c.current_evidence_version and c.owner_id=p_actor and c.claim_expires_at>now() and c.state='claimed');end if;
 else begin perform app_private.file_resolve_target(p_actor,i.purpose,i.evidence_action,i.parent_target_id);allowed:=true;exception when others then allowed:=false;end;end if;
 return coalesce(allowed,false) and(p_operation<>'download' or(i.id is not null and app_private.file_is_clean(p_file) and(a.publication_state<>'withdrawn' or app_private.has_role(p_actor,'admin') or p_actor=i.actor_id)));
end $$;
create function app_private.file_dto(p_file uuid,p_actor uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare i app_private.file_upload_intents%rowtype;s app_private.file_upload_states%rowtype;a app_private.file_access_states%rowtype;f app_private.files%rowtype;allowed boolean;publisher boolean:=false;begin
 if not app_private.file_current_access(p_file,p_actor) then raise exception 'NOT_FOUND';end if;select * into i from app_private.file_upload_intents where id=p_file;select * into s from app_private.file_upload_states where file_id=p_file;select * into a from app_private.file_access_states where file_id=p_file;select * into f from app_private.files where id=p_file;allowed:=app_private.file_current_access(p_file,p_actor,'download');
 if i.purpose='shared_handout' then begin perform app_private.file_resolve_target(p_actor,'shared_handout',null,i.parent_id);publisher:=true;exception when others then publisher:=false;end;end if;
 return jsonb_build_object('file_id',i.id,'purpose',i.purpose,'filename',i.filename,'detected_type',f.detected_mime,'size_bytes',i.size_bytes,'created_at',i.created_at,'upload_state',s.state,'scan_state',coalesce(a.scan_state,'pending'),'publication_state',coalesce(a.publication_state,case when i.purpose='shared_handout' then 'unpublished' else 'private' end),'integration_state',coalesce(a.integration_state,'verification_required'),'source_provenance',case when f.id is null then 'metadata_only' else 'stored_object' end,'version',coalesce(a.version,s.version),'can_download',allowed,'can_publish',coalesce(publisher and a.scan_state='clean' and a.publication_state in('unpublished','withdrawn'),false),'can_withdraw',coalesce(publisher and a.publication_state='published',false),'content_path',case when allowed then '/api/v1/files/'||i.id||'/content' end,'safe_error_code',a.safe_error_code);
end $$;
create function api.create_file_upload(p_purpose text,p_parent_id uuid,p_filename text,p_declared_type text,p_size_bytes bigint,p_checksum_sha256 text,p_evidence_action text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();target jsonb;ctx jsonb;file_id uuid:=gen_random_uuid();begin
 target:=app_private.file_resolve_target(actor,p_purpose,p_evidence_action,p_parent_id);
 if p_filename is null or length(p_filename) not between 1 and 255 or p_filename<>btrim(p_filename) or p_filename~'[[:cntrl:]/\\]' or p_filename in('.','..') or p_size_bytes is null or p_size_bytes<1 or p_size_bytes>(case when p_purpose in('receipt','review_evidence') then 5242880 else 26214400 end) or p_checksum_sha256 is null or p_checksum_sha256!~'^[a-f0-9]{64}$' then raise exception 'VALIDATION_ERROR';end if;
 if p_declared_type is null or not(case when p_purpose='statement_evidence' then p_declared_type in('text/csv','application/pdf') when p_purpose in('private_preparation','shared_handout') then p_declared_type in('application/pdf','image/png','image/jpeg','image/webp','application/vnd.openxmlformats-officedocument.presentationml.presentation') else p_declared_type in('application/pdf','image/png','image/jpeg','image/webp') end) then raise exception 'FILE_TYPE_INVALID';end if;
 ctx:=app_private.booking_begin(actor,'create_file_upload',jsonb_build_object('purpose',p_purpose,'parent_id',p_parent_id,'filename',p_filename,'declared_type',p_declared_type,'size_bytes',p_size_bytes,'checksum_sha256',p_checksum_sha256,'evidence_action',p_evidence_action),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 insert into app_private.file_upload_intents(id,actor_id,session_id,purpose,evidence_action,parent_target_id,parent_type,parent_id,internal_purpose,learner_id,charge_id,filename,declared_type,size_bytes,checksum_sha256)values(file_id,actor,(current_setting('request.jwt.claims',true)::jsonb->>'session_id')::uuid,p_purpose,p_evidence_action,p_parent_id,target->>'parent_type',(target->>'parent_id')::uuid,target->>'internal_purpose',(target->>'learner_id')::uuid,(target->>'charge_id')::uuid,p_filename,p_declared_type,p_size_bytes,p_checksum_sha256);
 insert into app_private.file_upload_states(file_id)values(file_id);perform set_config('response.status','201',true);return app_private.booking_finish(ctx,file_id,1,jsonb_build_object('file_id',file_id,'upload_path','/api/v1/files/'||file_id||'/content'),'file_upload_created',jsonb_build_object('file_id',file_id));
end $$;
create function api.get_file(p_file_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin return app_private.file_dto(p_file_id,app_private.require_actor());end $$;
create function api.authorize_file_content(p_file_id uuid,p_operation text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();i app_private.file_upload_intents%rowtype;ticket uuid;begin
 if p_operation not in('upload','download') or p_operation is null then raise exception 'VALIDATION_ERROR';end if;select * into i from app_private.file_upload_intents where id=p_file_id;
 if i.id is null then raise exception 'NOT_FOUND';end if;if p_operation='upload' then if i.actor_id<>actor then raise exception 'NOT_FOUND';end if;perform app_private.file_resolve_target(actor,i.purpose,i.evidence_action,i.parent_target_id);else if not app_private.file_current_access(i.id,actor,'download') then raise exception 'NOT_FOUND';end if;end if;
 insert into app_private.file_content_authorizations(file_id,actor_id,session_id,operation)values(i.id,actor,(current_setting('request.jwt.claims',true)::jsonb->>'session_id')::uuid,p_operation)returning id into ticket;return jsonb_build_object('authorization_id',ticket);
end $$;
create function app_private.file_check_authorization(p_file uuid,p_authorization uuid,p_operation text) returns app_private.file_content_authorizations language plpgsql security definer set search_path='' as $$
declare ticket app_private.file_content_authorizations%rowtype;i app_private.file_upload_intents%rowtype;begin
 select * into ticket from app_private.file_content_authorizations where id=p_authorization and file_id=p_file and operation=p_operation;if ticket.id is null or ticket.expires_at<=now() or not app_private.auth_session_active(ticket.actor_id,ticket.session_id) or not app_private.payment_verified_account(ticket.actor_id) then raise exception 'SESSION_REVOKED';end if;select * into i from app_private.file_upload_intents where id=p_file;
 if p_operation='upload' then if i.actor_id<>ticket.actor_id then raise exception 'NOT_FOUND';end if;perform app_private.file_resolve_target(ticket.actor_id,i.purpose,i.evidence_action,i.parent_target_id);elsif not app_private.file_current_access(i.id,ticket.actor_id,'download') then raise exception 'NOT_FOUND';end if;return ticket;
end $$;
create function app_private.prepare_file_content(p_file_id uuid,p_authorization_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare i app_private.file_upload_intents%rowtype;s app_private.file_upload_states%rowtype;a app_private.file_upload_attempts%rowtype;generation uuid:=gen_random_uuid();begin
 perform app_private.file_check_authorization(p_file_id,p_authorization_id,'upload');select * into i from app_private.file_upload_intents where id=p_file_id;select * into s from app_private.file_upload_states where file_id=p_file_id for update;
 if s.adopted_attempt_id is not null then insert into app_private.file_upload_attempts(file_id,authorization_id,object_key,object_version)select p_file_id,p_authorization_id,x.object_key,x.object_version from app_private.file_upload_attempts x where x.id=s.adopted_attempt_id returning * into a;else
  select * into a from app_private.file_upload_attempts where file_id=p_file_id and authorization_id=p_authorization_id order by created_at desc limit 1;
  if a.id is null then insert into app_private.file_upload_attempts(file_id,authorization_id,object_key,object_version)values(p_file_id,p_authorization_id,p_file_id||'/'||generation,generation)returning * into a;end if;update app_private.file_upload_states set state='uploading',updated_at=now()where file_id=p_file_id;
 end if;
 return jsonb_build_object('file_id',i.id,'attempt_id',a.id,'lease_token',a.lease_token,'object_key',a.object_key,'object_version',a.object_version,'filename',i.filename,'purpose',i.purpose,'declared_type',i.declared_type,'size_bytes',i.size_bytes,'checksum_sha256',i.checksum_sha256,'already_uploaded',s.adopted_attempt_id is not null,'version',s.version);
end $$;
create function app_private.record_file_object(p_file_id uuid,p_attempt_id uuid,p_lease_token uuid,p_observation jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare i app_private.file_upload_intents%rowtype;s app_private.file_upload_states%rowtype;a app_private.file_upload_attempts%rowtype;begin
 select * into a from app_private.file_upload_attempts where id=p_attempt_id and file_id=p_file_id and lease_token=p_lease_token;if a.id is null then raise exception 'LEASE_LOST';end if;perform app_private.file_check_authorization(p_file_id,a.authorization_id,'upload');select * into i from app_private.file_upload_intents where id=p_file_id;select * into s from app_private.file_upload_states where file_id=p_file_id for update;
 if p_observation is null or p_observation<>jsonb_build_object('size_bytes',i.size_bytes,'checksum_sha256',i.checksum_sha256,'detected_type',i.declared_type) then raise exception 'VALIDATION_ERROR';end if;
 insert into app_private.file_object_observations(attempt_id,observation)values(a.id,p_observation)on conflict do nothing;
 if s.adopted_attempt_id is null then
  insert into app_private.files(id,uploader_account_id,learner_id,charge_id,parent_type,parent_id,purpose,object_key,object_version,checksum_sha256,detected_mime,byte_size,scan_state,source_provenance)values(i.id,i.actor_id,i.learner_id,i.charge_id,i.parent_type,i.parent_id,i.internal_purpose,a.object_key,a.object_version::text,i.checksum_sha256,i.declared_type,i.size_bytes,'pending','stored_object');
  update app_private.file_upload_states set state='uploaded',adopted_attempt_id=a.id,version=version+1,updated_at=now()where file_id=i.id returning * into s;
  insert into app_private.file_access_states(file_id,publication_state,version)values(i.id,case when i.purpose='shared_handout' then 'unpublished' else 'private' end,s.version);
 end if;
 return jsonb_build_object('file_id',i.id,'upload_state','uploaded','size_bytes',i.size_bytes,'checksum_sha256',i.checksum_sha256,'version',s.version);
end $$;
create function app_private.prepare_file_download(p_file_id uuid,p_authorization_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare f app_private.files%rowtype;name text;begin perform app_private.file_check_authorization(p_file_id,p_authorization_id,'download');select * into strict f from app_private.files where id=p_file_id;select filename into name from app_private.file_upload_intents where id=p_file_id;return jsonb_build_object('file_id',f.id,'object_key',f.object_key,'object_version',f.object_version,'filename',name,'detected_type',f.detected_mime,'size_bytes',f.byte_size,'checksum_sha256',f.checksum_sha256);end $$;
create function api.finalize_file_upload(p_file_id uuid,p_checksum_sha256 text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();i app_private.file_upload_intents%rowtype;s app_private.file_upload_states%rowtype;ctx jsonb;job uuid;begin
 select * into i from app_private.file_upload_intents where id=p_file_id;if i.id is null or i.actor_id<>actor then raise exception 'NOT_FOUND';end if;perform app_private.file_resolve_target(actor,i.purpose,i.evidence_action,i.parent_target_id);ctx:=app_private.booking_begin(actor,'finalize_file_upload',jsonb_build_object('file_id',p_file_id,'checksum_sha256',p_checksum_sha256),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 select * into s from app_private.file_upload_states where file_id=p_file_id for update;if i.checksum_sha256 is distinct from p_checksum_sha256 then raise exception 'FILE_CHECKSUM_MISMATCH';end if;if s.adopted_attempt_id is null then raise exception 'UPLOAD_REQUIRED';end if;
 job:=s.scan_job_id;if job is null then job:=app_private.enqueue_event(gen_random_uuid(),'file_scan_requested',i.id,jsonb_build_object('file_id',i.id),'files.scan');update app_private.file_upload_states set state='finalized',scan_job_id=job,version=version+1,updated_at=now()where file_id=i.id returning * into s;perform set_config('response.status','202',true);end if;
 return app_private.booking_finish(ctx,i.id,s.version,jsonb_build_object('scan_state',(select scan_state from app_private.file_access_states where file_id=i.id),'scan_job_id',job),'file_upload_finalized',jsonb_build_object('file_id',i.id));
end $$;
create function app_private.prepare_file_scan(p_file_id uuid,p_job_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare f app_private.files%rowtype;a app_private.file_access_states%rowtype;scenario text:='clean';completed jsonb;begin
 if not exists(select 1 from app_private.outbox_jobs j join app_private.domain_events e on e.id=j.event_id where j.id=p_job_id and j.purpose='files.scan' and j.state='leased' and j.lease_token=p_lease_token and j.lease_expires_at>now() and e.aggregate_id=p_file_id and e.event_type='file_scan_requested' and e.payload=jsonb_build_object('file_id',p_file_id)) then raise exception 'LEASE_LOST';end if;
 select * into f from app_private.files where id=p_file_id;select * into a from app_private.file_access_states where file_id=p_file_id;if f.id is null or a.file_id is null then raise exception 'NOT_FOUND';end if;
 insert into app_private.file_scan_attempts(file_id,scan_generation,job_id,lease_token,object_version,checksum_sha256)values(f.id,a.scan_generation,p_job_id,p_lease_token,f.object_version,f.checksum_sha256)on conflict do nothing;
 if exists(select 1 from app_private.environment_metadata where environment in('test','development') and fixture_marker is not null)then select coalesce((select s.scenario from app_private.file_scan_scenarios s where s.file_id=p_file_id),'clean')into scenario;end if;select result into completed from app_private.file_scan_results where job_id=p_job_id;
 return jsonb_build_object('file_id',f.id,'scan_generation',a.scan_generation,'object_key',f.object_key,'object_version',f.object_version,'checksum_sha256',f.checksum_sha256,'detected_type',f.detected_mime,'size_bytes',f.byte_size,'scenario',scenario,'completed_result',completed);
end $$;
create function app_private.finalize_file_scan(p_file_id uuid,p_scan_generation integer,p_job_id uuid,p_lease_token uuid,p_observation jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare prepared jsonb;attempt uuid;a app_private.file_access_states%rowtype;result jsonb;result_id uuid:=gen_random_uuid();scan text;mode text;publicpurpose text;begin
 prepared:=app_private.prepare_file_scan(p_file_id,p_job_id,p_lease_token);if prepared->'completed_result'<>'null'::jsonb then return prepared->'completed_result';end if;
 if p_observation is null or jsonb_typeof(p_observation)<>'object' or p_observation-array['outcome','adapter_mode','engine_version','signature_version','reference','safe_error_code']<>'{}'::jsonb or not(p_observation ?& array['outcome','adapter_mode','engine_version','signature_version','reference','safe_error_code']) or p_observation->>'outcome' not in('clean','infected','error','unknown') or p_observation->>'adapter_mode' not in('fake','clamav') then raise exception 'VALIDATION_ERROR';end if;
 mode:=p_observation->>'adapter_mode';if mode='fake' and not exists(select 1 from app_private.environment_metadata where environment in('test','development') and fixture_marker is not null)then raise exception 'FORBIDDEN';end if;
 if length(p_observation->>'engine_version')not between 1 and 200 or length(p_observation->>'signature_version')not between 1 and 200 or length(p_observation->>'reference')not between 1 and 200 or(p_observation->>'safe_error_code' is not null and p_observation->>'safe_error_code'!~'^[A-Z0-9_]{1,80}$')then raise exception 'VALIDATION_ERROR';end if;
 select * into a from app_private.file_access_states where file_id=p_file_id for update;select id into attempt from app_private.file_scan_attempts where job_id=p_job_id and lease_token=p_lease_token;
 scan:=case when p_observation->>'outcome'='clean' then 'clean' else 'quarantined' end;
 if a.scan_generation=p_scan_generation then update app_private.file_access_states set scan_state=scan,integration_state=case when mode='fake' then 'simulated' else 'verified' end,safe_error_code=p_observation->>'safe_error_code',current_scan_result_id=result_id,version=version+1,updated_at=now()where file_id=p_file_id returning * into a;end if;
 result:=jsonb_build_object('file_id',p_file_id,'scan_state',a.scan_state,'version',a.version);insert into app_private.file_scan_results(id,file_id,scan_generation,job_id,attempt_id,observation,result)values(result_id,p_file_id,p_scan_generation,p_job_id,attempt,p_observation,result);
 select purpose into publicpurpose from app_private.file_upload_intents where id=p_file_id;if a.scan_generation=p_scan_generation and scan='clean' and publicpurpose='private_preparation' then perform app_private.enqueue_event(gen_random_uuid(),'preparation_ready',p_file_id,jsonb_build_object('file_id',p_file_id),'notifications.route');end if;
 return result;
end $$;
create function app_private.file_publication_command(p_file uuid,p_action text,p_reason text,p_version integer,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();i app_private.file_upload_intents%rowtype;a app_private.file_access_states%rowtype;ctx jsonb;begin
 select * into i from app_private.file_upload_intents where id=p_file;if i.id is null or i.purpose<>'shared_handout' then raise exception 'NOT_FOUND';end if;perform app_private.file_resolve_target(actor,i.purpose,null,i.parent_id);
 ctx:=app_private.booking_begin(actor,case when p_action='published' then 'publish_shared_file' else 'withdraw_shared_file' end,jsonb_build_object('file_id',p_file,'action',p_action,'reason',p_reason,'expected_version',p_version),p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;select * into a from app_private.file_access_states where file_id=p_file for update;if a.file_id is null or not app_private.file_is_clean(p_file)then raise exception 'SCAN_REQUIRED';end if;if a.version<>p_version then raise exception 'VERSION_CONFLICT';end if;if p_action='withdrawn' and(a.publication_state<>'published' or length(btrim(p_reason))not between 1 and 2000)then raise exception 'STATE_CONFLICT';end if;
 update app_private.file_access_states set publication_state=p_action,version=version+1,updated_at=now()where file_id=p_file returning * into a;insert into app_private.file_publications(file_id,actor_id,action,reason,access_version,command_id)values(p_file,actor,p_action,p_reason,a.version,(ctx->>'command_id')::uuid);
 return app_private.booking_finish(ctx,p_file,a.version,jsonb_build_object('publication_state',p_action),case when p_action='published' then 'handout_ready' else 'handout_withdrawn' end,jsonb_build_object('file_id',p_file));
end $$;
create function api.publish_shared_file(p_file_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.file_publication_command(p_file_id,'published',null,p_expected_version,p_idempotency_key)$$;
create function api.withdraw_shared_file(p_file_id uuid,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.file_publication_command(p_file_id,'withdrawn',p_reason,p_expected_version,p_idempotency_key)$$;
create function api.list_files(p_enrollment_id uuid default null,p_occurrence_id uuid default null,p_purpose text default null,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();e app_private.enrollments%rowtype;o app_private.occurrences%rowtype;rows jsonb;after_at timestamptz;after_id uuid;begin
 if(p_enrollment_id is null)=(p_occurrence_id is null)or p_limit is null or p_limit not between 1 and 100 or(p_purpose is not null and p_purpose not in('private_preparation','shared_handout'))then raise exception 'VALIDATION_ERROR';end if;
 if p_enrollment_id is not null then select * into e from app_private.enrollments where id=p_enrollment_id;select * into o from app_private.occurrences where id=e.occurrence_id;if e.id is null or not(app_private.file_material_scope(actor,e.learner_id)or app_private.has_role(actor,'admin')or exists(select 1 from app_private.tutors t where t.id=o.tutor_id and t.account_id=actor and app_private.has_role(actor,'tutor')))then raise exception 'NOT_FOUND';end if;
 else select * into o from app_private.occurrences where id=p_occurrence_id;if o.id is null or not(app_private.has_role(actor,'admin')or exists(select 1 from app_private.tutors t where t.id=o.tutor_id and t.account_id=actor and app_private.has_role(actor,'tutor'))or exists(select 1 from app_private.enrollments en where en.occurrence_id=o.id and en.state='confirmed' and app_private.file_material_scope(actor,en.learner_id)))then raise exception 'NOT_FOUND';end if;end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.file_dto(x.id,actor))order by x.created_at desc,x.id desc),'[]')into rows from(select i.* from app_private.file_upload_intents i where((i.parent_type='enrollment' and i.parent_id=p_enrollment_id)or(i.parent_type='occurrence' and i.parent_id=o.id))and(p_purpose is null or i.purpose=p_purpose)and app_private.file_current_access(i.id,actor)and(p_cursor is null or(i.created_at,i.id)<(after_at,after_id))order by i.created_at desc,i.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);
end $$;
create function api.list_my_material_enrollments(p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();rows jsonb;after_at timestamptz;after_id uuid;begin
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;if p_cursor is not null then after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',jsonb_build_object('enrollment_id',x.id,'learner',jsonb_build_object('learner_id',x.learner_id,'display_name',x.display_name),'occurrence',jsonb_build_object('occurrence_id',x.occurrence_id,'title',x.title,'start_at',x.start_at,'end_at',x.end_at)))order by x.created_at desc,x.id desc),'[]')into rows from(select e.id,e.created_at,e.learner_id,e.occurrence_id,p.display_name,s.title,o.start_at,o.end_at from app_private.enrollments e join app_private.learners l on l.id=e.learner_id join app_private.people p on p.id=l.person_id join app_private.occurrences o on o.id=e.occurrence_id join app_private.offers f on f.id=o.offer_id join app_private.subjects s on s.id=f.subject_id where e.state in('held','confirmed','completed')and app_private.file_material_scope(actor,e.learner_id)and(p_cursor is null or(e.created_at,e.id)<(after_at,after_id))order by e.created_at desc,e.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);
end $$;
create or replace function app_private.payment_file_dto(p_file uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();f app_private.files%rowtype;begin select * into f from app_private.files where id=p_file;return jsonb_build_object('file_id',f.id,'purpose',f.purpose,'checksum_sha256',f.checksum_sha256,'detected_mime',f.detected_mime,'byte_size',f.byte_size,'scan_state',coalesce((select scan_state from app_private.file_access_states where file_id=f.id),f.scan_state),'source_provenance',f.source_provenance,'created_at',f.created_at,'can_download',app_private.file_current_access(f.id,actor,'download'));end $$;
create or replace function api.list_payment_evidence(p_action text,p_target_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();target jsonb;purpose text;after_at timestamptz;after_id uuid;rows jsonb;begin
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;
 purpose:=case when p_action in('submit_receipt','replace_receipt')then 'receipt' when p_action in('create_statement_import','record_manual_transfer','verify_transfer_settlement')then 'statement_evidence' else 'review_evidence' end;target:=app_private.file_resolve_target(actor,purpose,p_action,p_target_id);
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_file_dto(x.id))order by x.created_at desc,x.id desc),'[]')into rows from(select f.* from app_private.files f where f.purpose=target->>'internal_purpose' and f.parent_type=target->>'parent_type' and f.parent_id is not distinct from(target->>'parent_id')::uuid and(p_action not in('submit_receipt','replace_receipt','create_receiving_account','propose_refund_destination')or f.uploader_account_id=actor)and app_private.file_is_clean(f.id)and(p_cursor is null or(f.created_at,f.id)<(after_at,after_id))order by f.created_at desc,f.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);
end $$;
-- Preserve prior business bodies; replace only their legacy immutable metadata clean predicates.
do $$declare f record;definition text;begin
 for f in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='app_private' and p.proname in('payment_assert_file','payment_read_page','payment_receipt_dto')loop
  definition:=pg_get_functiondef(f.oid);definition:=replace(definition,'f.scan_state<>''clean''','not app_private.file_is_clean(f.id)');definition:=replace(definition,'f.scan_state=''clean''','app_private.file_is_clean(f.id)');definition:=replace(definition,'x.scan_state=''''clean''''','app_private.file_is_clean(x.id)');execute definition;
 end loop;
end $$;
do $$declare t record;begin
 for t in select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app_private'and c.relkind='r'and c.relname in('file_upload_intents','file_upload_states','file_content_authorizations','file_upload_attempts','file_object_observations','file_access_states','file_scan_attempts','file_scan_results','file_publications','file_scan_scenarios')loop
  execute format('alter table app_private.%I enable row level security',t.relname);execute format('create policy commands_access on app_private.%I to git_tutor_commands using(true)with check(true)',t.relname);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t.relname);execute format('grant select,insert on app_private.%I to git_tutor_commands',t.relname);
  if t.relname in('file_upload_states','file_access_states')then execute format('grant update on app_private.%I to git_tutor_commands',t.relname);else execute format('create trigger file_immutable before update or delete on app_private.%I for each row execute function app_private.reject_immutable_change()',t.relname);end if;
 end loop;
end $$;
do $$declare f record;begin
 for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and p.proname=any(array['file_material_scope','file_resolve_target','file_is_clean','file_current_access','file_dto','create_file_upload','get_file','authorize_file_content','file_check_authorization','prepare_file_content','record_file_object','prepare_file_download','finalize_file_upload','prepare_file_scan','finalize_file_scan','file_publication_command','publish_shared_file','withdraw_shared_file','list_files','list_my_material_enrollments','payment_file_dto','list_payment_evidence'])loop
  execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);elsif f.proname in('prepare_file_content','record_file_object','prepare_file_download','prepare_file_scan','finalize_file_scan')then execute format('grant execute on function %s to git_tutor_worker',f.signature);end if;
 end loop;
end $$;
revoke create on schema api,app_private from git_tutor_commands;notify pgrst,'reload schema';

